import { queryOptions } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import type { Question, QuestionCategory } from "@/data/questions";

const CATEGORIES: QuestionCategory[] = [
  "Vägmärken",
  "Trafikregler",
  "Miljö",
  "Människan & Trafiken",
  "Fordonskännedom",
];

function isCategory(value: string): value is QuestionCategory {
  return (CATEGORIES as string[]).includes(value);
}

/** Questions generated by AI and stored permanently in the shared question bank. */
export async function fetchBankQuestions(): Promise<Question[]> {
  const { data, error } = await supabase
    .from("ai_questions")
    .select("id, category, question, options, correct, explanation, reference, image")
    .order("created_at", { ascending: true });

  if (error) throw new Error(error.message);

  return (data ?? []).flatMap((row): Question[] => {
    const options = Array.isArray(row.options) ? row.options.map((o) => String(o)) : [];
    if (options.length !== 4 || !isCategory(row.category)) return [];
    return [
      {
        id: `ai-${row.id}`,
        category: row.category,
        question: row.question,
        options,
        correct: row.correct,
        explanation: row.explanation,
        reference: row.reference,
        ...(row.image ? { image: row.image } : {}),
      },
    ];
  });
}

export const bankQuestionsQuery = queryOptions({
  queryKey: ["ai-questions"],
  queryFn: fetchBankQuestions,
  // Banken ändras bara via adminpanelen – hämta om vid behov, inte vid varje besök.
  staleTime: 5 * 60_000,
  gcTime: 30 * 60_000,
});

